using System; using System.Windows; using System.Windows.Controls; using SaveProfileSwitcher.App.Models; namespace SaveProfileSwitcher.App.Views; public partial class EditGameDialog : Window { public GameConfig EditedGame{get;private set;} public EditGameDialog(GameConfig game){ArgumentNullException.ThrowIfNull(game);EditedGame=game;InitializeComponent();LoadGameIntoControls(game);} private void LoadGameIntoControls(GameConfig game){GameTitleTextBox.Text=game.GameName;TitleIdTextBox.Text=game.EmulatorConfig?.TitleId??string.Empty;SaveDirectoryTextBox.Text=game.EmulatorConfig?.SaveRootPath??string.Empty;ExecutablePathTextBox.Text=game.EmulatorConfig?.ExecutablePath??string.Empty;PlatformComboBox.SelectedIndex=0;SaveModeComboBox.SelectedIndex=0;RequiredField_TextChanged(this,null!);} private void RequiredField_TextChanged(object sender,TextChangedEventArgs e){SaveButton.IsEnabled=!string.IsNullOrWhiteSpace(GameTitleTextBox.Text)&&!string.IsNullOrWhiteSpace(TitleIdTextBox.Text)&&!string.IsNullOrWhiteSpace(SaveDirectoryTextBox.Text);} private void SaveButton_Click(object sender,RoutedEventArgs e){EditedGame.GameName=GameTitleTextBox.Text.Trim();EditedGame.EmulatorConfig??=new EmulatorConfig();EditedGame.EmulatorConfig.TitleId=TitleIdTextBox.Text.Trim();EditedGame.EmulatorConfig.SaveRootPath=SaveDirectoryTextBox.Text.Trim();EditedGame.EmulatorConfig.ExecutablePath=ExecutablePathTextBox.Text.Trim();DialogResult=true;} private void Cancel_Click(object sender,RoutedEventArgs e){DialogResult=false;} }